/**
 * @file getElementBounds - Get element bounding rect
 * @module @dsai-io/react/utils/layout
 *
 * Retrieves the bounding client rect of an element with SSR safety
 * and additional computed values for layout calculations.
 *
 * Features:
 * - SSR-safe (returns null when DOM unavailable)
 * - Includes scroll-adjusted coordinates
 * - Provides center point calculations
 * - Cached rect to avoid forced reflows
 * - TypeScript-friendly with strict types
 */

import { isBrowser } from '../browser/isBrowser';

/**
 * Element bounds with extended measurements
 */
export interface ElementBounds {
  /** Distance from top of viewport */
  readonly top: number;
  /** Distance from left of viewport */
  readonly left: number;
  /** Distance from right of viewport */
  readonly right: number;
  /** Distance from bottom of viewport */
  readonly bottom: number;
  /** Element width */
  readonly width: number;
  /** Element height */
  readonly height: number;
  /** Horizontal center point */
  readonly centerX: number;
  /** Vertical center point */
  readonly centerY: number;
  /** Distance from document top (scroll-adjusted) */
  readonly absoluteTop: number;
  /** Distance from document left (scroll-adjusted) */
  readonly absoluteLeft: number;
}

/**
 * Options for getElementBounds
 */
export interface GetElementBoundsOptions {
  /**
   * Include scroll offset for absolute positioning.
   * @default true
   */
  includeScrollOffset?: boolean;
}

/**
 * Gets the bounding rect of an element with extended measurements.
 *
 * @param element - The DOM element to measure
 * @param options - Optional configuration
 * @returns Element bounds or null if SSR/invalid element
 *
 * @example
 * ```tsx
 * const bounds = getElementBounds(myElement);
 * if (bounds) {
 *   console.log(`Element is at (${bounds.left}, ${bounds.top})`);
 *   console.log(`Center point: (${bounds.centerX}, ${bounds.centerY})`);
 *   console.log(`Absolute position: (${bounds.absoluteLeft}, ${bounds.absoluteTop})`);
 * }
 *
 * // Without scroll offset
 * const viewportBounds = getElementBounds(myElement, { includeScrollOffset: false });
 * ```
 */
export function getElementBounds(
  element: Element | null | undefined,
  options: GetElementBoundsOptions = {}
): ElementBounds | null {
  // SSR safety check
  if (!isBrowser()) {
    return null;
  }

  // Null/undefined element check
  if (element === null || element === undefined) {
    return null;
  }

  // Validate element has getBoundingClientRect
  if (typeof element.getBoundingClientRect !== 'function') {
    return null;
  }

  const { includeScrollOffset = true } = options;

  try {
    const rect = element.getBoundingClientRect();

    // Get scroll offsets
    const scrollX = includeScrollOffset ? window.scrollX : 0;
    const scrollY = includeScrollOffset ? window.scrollY : 0;

    return {
      top: rect.top,
      left: rect.left,
      right: rect.right,
      bottom: rect.bottom,
      width: rect.width,
      height: rect.height,
      centerX: rect.left + rect.width / 2,
      centerY: rect.top + rect.height / 2,
      absoluteTop: rect.top + scrollY,
      absoluteLeft: rect.left + scrollX,
    };
  } catch {
    // Handle edge cases where getBoundingClientRect might throw
    return null;
  }
}

/**
 * Checks if two element bounds intersect.
 *
 * @param a - First bounds
 * @param b - Second bounds
 * @returns True if bounds intersect
 *
 * @example
 * ```tsx
 * const boundsA = getElementBounds(elementA);
 * const boundsB = getElementBounds(elementB);
 *
 * if (boundsA && boundsB && boundsIntersect(boundsA, boundsB)) {
 *   console.log('Elements are overlapping!');
 * }
 * ```
 */
export function boundsIntersect(a: ElementBounds, b: ElementBounds): boolean {
  // Use <= to ensure touching edges are NOT considered intersecting
  return !(a.right <= b.left || a.left >= b.right || a.bottom <= b.top || a.top >= b.bottom);
}

/**
 * Checks if an element's bounds are within the viewport.
 *
 * @param bounds - Element bounds to check
 * @param threshold - Percentage of element that must be visible (0-1)
 * @returns True if element is visible within threshold
 *
 * @example
 * ```tsx
 * const bounds = getElementBounds(element);
 * if (bounds && isInViewport(bounds, 0.5)) {
 *   console.log('At least 50% of element is visible');
 * }
 * ```
 */
export function isInViewport(bounds: ElementBounds, threshold = 0): boolean {
  if (!isBrowser()) {
    return false;
  }

  const viewportWidth = window.innerWidth;
  const viewportHeight = window.innerHeight;

  // Calculate visible portion
  const visibleLeft = Math.max(0, bounds.left);
  const visibleRight = Math.min(viewportWidth, bounds.right);
  const visibleTop = Math.max(0, bounds.top);
  const visibleBottom = Math.min(viewportHeight, bounds.bottom);

  const visibleWidth = Math.max(0, visibleRight - visibleLeft);
  const visibleHeight = Math.max(0, visibleBottom - visibleTop);

  const visibleArea = visibleWidth * visibleHeight;
  const totalArea = bounds.width * bounds.height;

  // Return false if no visible area (element completely outside viewport)
  if (visibleArea === 0) {
    return false;
  }

  // Avoid division by zero
  if (totalArea === 0) {
    return false;
  }

  const visibleRatio = visibleArea / totalArea;
  return visibleRatio >= threshold;
}

/**
 * @file getViewportSize - Get viewport dimensions
 * @module @dsai-io/react/utils/layout
 *
 * Retrieves viewport dimensions with SSR safety and multiple
 * measurement strategies for different use cases.
 *
 * Features:
 * - SSR-safe (returns default dimensions when DOM unavailable)
 * - Multiple measurement strategies (innerWidth/clientWidth)
 * - Excludes scrollbar width when needed
 * - Provides aspect ratio calculation
 * - TypeScript-friendly with strict types
 */

import { isBrowser } from '../browser/isBrowser';

/**
 * Viewport size measurements
 */
export interface ViewportSize {
  /** Viewport width including scrollbar */
  readonly width: number;
  /** Viewport height including scrollbar */
  readonly height: number;
  /** Viewport width excluding scrollbar */
  readonly clientWidth: number;
  /** Viewport height excluding scrollbar */
  readonly clientHeight: number;
  /** Aspect ratio (width / height) */
  readonly aspectRatio: number;
  /** True if viewport is in portrait orientation */
  readonly isPortrait: boolean;
  /** True if viewport is in landscape orientation */
  readonly isLandscape: boolean;
}

/**
 * Options for getViewportSize
 */
export interface GetViewportSizeOptions {
  /**
   * Default width to return in SSR environment.
   * @default 0
   */
  defaultWidth?: number;

  /**
   * Default height to return in SSR environment.
   * @default 0
   */
  defaultHeight?: number;
}

/**
 * Gets the current viewport dimensions.
 *
 * @param options - Optional configuration
 * @returns Viewport size measurements
 *
 * @example
 * ```tsx
 * const viewport = getViewportSize();
 * console.log(`Viewport: ${viewport.width}x${viewport.height}`);
 * console.log(`Aspect ratio: ${viewport.aspectRatio.toFixed(2)}`);
 *
 * if (viewport.isPortrait) {
 *   console.log('Mobile layout');
 * }
 *
 * // SSR with defaults
 * const ssrViewport = getViewportSize({ defaultWidth: 1920, defaultHeight: 1080 });
 * ```
 */
export function getViewportSize(options: GetViewportSizeOptions = {}): ViewportSize {
  const { defaultWidth = 0, defaultHeight = 0 } = options;

  // SSR safety check
  if (!isBrowser()) {
    const aspectRatio = defaultHeight > 0 ? defaultWidth / defaultHeight : 1;
    return {
      width: defaultWidth,
      height: defaultHeight,
      clientWidth: defaultWidth,
      clientHeight: defaultHeight,
      aspectRatio,
      isPortrait: defaultHeight > defaultWidth,
      isLandscape: defaultWidth > defaultHeight,
    };
  }

  // innerWidth/innerHeight include scrollbars
  const width = window.innerWidth;
  const height = window.innerHeight;

  // clientWidth/clientHeight exclude scrollbars
  const documentElement = document.documentElement;
  const clientWidth = documentElement.clientWidth;
  const clientHeight = documentElement.clientHeight;

  const aspectRatio = height > 0 ? width / height : 1;

  return {
    width,
    height,
    clientWidth,
    clientHeight,
    aspectRatio,
    isPortrait: height > width,
    isLandscape: width > height,
  };
}

/**
 * Gets the document scroll dimensions.
 *
 * @returns Document scroll dimensions or null in SSR
 *
 * @example
 * ```tsx
 * const scroll = getDocumentSize();
 * if (scroll) {
 *   console.log(`Document is ${scroll.height}px tall`);
 *   console.log(`Scroll progress: ${(scroll.scrollTop / scroll.maxScrollY * 100).toFixed(0)}%`);
 * }
 * ```
 */
export interface DocumentSize {
  /** Full document width */
  readonly width: number;
  /** Full document height */
  readonly height: number;
  /** Current horizontal scroll position */
  readonly scrollLeft: number;
  /** Current vertical scroll position */
  readonly scrollTop: number;
  /** Maximum horizontal scroll */
  readonly maxScrollX: number;
  /** Maximum vertical scroll */
  readonly maxScrollY: number;
}

/**
 * Gets the document scroll dimensions and position.
 *
 * @returns Document size or null in SSR
 */
export function getDocumentSize(): DocumentSize | null {
  if (!isBrowser()) {
    return null;
  }

  const documentElement = document.documentElement;
  const body = document.body;

  // Get the maximum of documentElement and body to handle quirks mode
  const width = Math.max(
    documentElement.scrollWidth,
    body.scrollWidth,
    documentElement.offsetWidth,
    body.offsetWidth,
    documentElement.clientWidth
  );

  const height = Math.max(
    documentElement.scrollHeight,
    body.scrollHeight,
    documentElement.offsetHeight,
    body.offsetHeight,
    documentElement.clientHeight
  );

  const scrollLeft = window.scrollX;
  const scrollTop = window.scrollY;

  const viewportWidth = window.innerWidth;
  const viewportHeight = window.innerHeight;

  return {
    width,
    height,
    scrollLeft,
    scrollTop,
    maxScrollX: Math.max(0, width - viewportWidth),
    maxScrollY: Math.max(0, height - viewportHeight),
  };
}

/**
 * Gets the scroll percentage of the document.
 *
 * @returns Scroll percentage (0-1) or 0 in SSR
 *
 * @example
 * ```tsx
 * const progress = getScrollProgress();
 * progressBar.style.width = `${progress * 100}%`;
 * ```
 */
export function getScrollProgress(): number {
  const docSize = getDocumentSize();
  if (!docSize || docSize.maxScrollY === 0) {
    return 0;
  }
  return Math.min(1, Math.max(0, docSize.scrollTop / docSize.maxScrollY));
}

/**
 * @file Layout utilities barrel export
 * @module @dsai-io/react/utils/layout
 *
 * Enterprise-grade layout and measurement utilities.
 * All utilities are SSR-safe and provide cleanup functions where applicable.
 */

// Element bounds and viewport measurements
export { boundsIntersect, getElementBounds, isInViewport } from './getElementBounds';
export type { ElementBounds, GetElementBoundsOptions } from './getElementBounds';

export { getDocumentSize, getScrollProgress, getViewportSize } from './getViewportSize';
export type { DocumentSize, GetViewportSizeOptions, ViewportSize } from './getViewportSize';

// ResizeObserver wrapper
export { observeResize, observeResizeMany } from './observeResize';
export type {
  ObserveResizeOptions,
  ResizeCallback,
  ResizeCleanup,
  ResizeEntry,
} from './observeResize';

// Animation frame scheduling
export { scheduleFrame, scheduleFrameAfter, startLoop } from './scheduleFrame';
export type { FrameCallback, FrameCleanup, FrameInfo, LoopCallback } from './scheduleFrame';

// Frame throttling
export { rafThrottle, throttleFrame } from './throttleFrame';
export type { ThrottleFrameOptions, ThrottledFrameFunction } from './throttleFrame';

/**
 * @file observeResize - ResizeObserver wrapper with cleanup
 * @module @dsai-io/react/utils/layout
 *
 * A wrapper around ResizeObserver that provides automatic cleanup,
 * debouncing, and SSR safety.
 *
 * Features:
 * - SSR-safe (no-op when ResizeObserver unavailable)
 * - Automatic cleanup function returned
 * - Optional debouncing to prevent excessive callbacks
 * - Simplified callback signature
 * - Box model options (content-box, border-box, device-pixel-content-box)
 * - TypeScript-friendly with strict types
 */

import { isBrowser } from '../browser/isBrowser';

/**
 * Resize entry with simplified measurements
 */
export interface ResizeEntry {
  /** The observed element */
  readonly target: Element;
  /** Element width */
  readonly width: number;
  /** Element height */
  readonly height: number;
  /** Content rect (for detailed measurements) */
  readonly contentRect: DOMRectReadOnly;
  /** Border box size (if available) */
  readonly borderBoxSize?: readonly ResizeObserverSize[];
  /** Content box size (if available) */
  readonly contentBoxSize?: readonly ResizeObserverSize[];
}

/**
 * Callback for resize observations
 */
export type ResizeCallback = (entry: ResizeEntry) => void;

/**
 * Options for observeResize
 */
export interface ObserveResizeOptions {
  /**
   * Which box model to observe.
   * @default 'content-box'
   */
  box?: ResizeObserverBoxOptions;

  /**
   * Debounce delay in milliseconds.
   * Set to 0 to disable debouncing.
   * @default 0
   */
  debounce?: number;
}

/**
 * Cleanup function to stop observing
 */
export type ResizeCleanup = () => void;

/**
 * Observes an element for size changes.
 *
 * @param element - Element to observe
 * @param callback - Function called on resize
 * @param options - Optional configuration
 * @returns Cleanup function to stop observing
 *
 * @example
 * ```tsx
 * // Basic usage
 * const cleanup = observeResize(myElement, (entry) => {
 *   console.log(`New size: ${entry.width}x${entry.height}`);
 * });
 *
 * // Cleanup when done
 * cleanup();
 *
 * // With debouncing
 * const cleanup = observeResize(
 *   myElement,
 *   (entry) => handleResize(entry),
 *   { debounce: 100 }
 * );
 *
 * // In React useEffect
 * useEffect(() => {
 *   const cleanup = observeResize(ref.current, handleResize);
 *   return cleanup;
 * }, []);
 * ```
 */
export function observeResize(
  element: Element | null | undefined,
  callback: ResizeCallback,
  options: ObserveResizeOptions = {}
): ResizeCleanup {
  // SSR safety check
  if (!isBrowser()) {
    return () => {
      // No-op cleanup
    };
  }

  // Check for ResizeObserver support
  if (typeof ResizeObserver === 'undefined') {
    return () => {
      // No-op cleanup
    };
  }

  // Null/undefined element check
  if (element === null || element === undefined) {
    return () => {
      // No-op cleanup
    };
  }

  const { box = 'content-box', debounce: debounceMs = 0 } = options;

  let timeoutId: ReturnType<typeof setTimeout> | null = null;
  let lastEntry: ResizeEntry | null = null;

  const debouncedCallback = (entry: ResizeEntry): void => {
    if (debounceMs <= 0) {
      callback(entry);
      return;
    }

    lastEntry = entry;

    if (timeoutId !== null) {
      clearTimeout(timeoutId);
    }

    timeoutId = setTimeout(() => {
      if (lastEntry !== null) {
        callback(lastEntry);
        lastEntry = null;
      }
      timeoutId = null;
    }, debounceMs);
  };

  const observer = new ResizeObserver((entries) => {
    for (const entry of entries) {
      const resizeEntry: ResizeEntry = {
        target: entry.target,
        width: entry.contentRect.width,
        height: entry.contentRect.height,
        contentRect: entry.contentRect,
        borderBoxSize: entry.borderBoxSize,
        contentBoxSize: entry.contentBoxSize,
      };
      debouncedCallback(resizeEntry);
    }
  });

  try {
    observer.observe(element, { box });
  } catch {
    // Some browsers may not support all box options
    try {
      observer.observe(element);
    } catch {
      // If observation fails entirely, return no-op
      return () => {
        // No-op cleanup
      };
    }
  }

  return () => {
    if (timeoutId !== null) {
      clearTimeout(timeoutId);
    }
    observer.disconnect();
  };
}

/**
 * Observes multiple elements for size changes.
 *
 * @param elements - Elements to observe
 * @param callback - Function called on resize (includes target element)
 * @param options - Optional configuration
 * @returns Cleanup function to stop observing all elements
 *
 * @example
 * ```tsx
 * const cleanup = observeResizeMany(
 *   [element1, element2, element3],
 *   (entry) => {
 *     console.log(`${entry.target.id} resized to ${entry.width}x${entry.height}`);
 *   }
 * );
 *
 * // Cleanup all observations
 * cleanup();
 * ```
 */
export function observeResizeMany(
  elements: readonly (Element | null | undefined)[],
  callback: ResizeCallback,
  options: ObserveResizeOptions = {}
): ResizeCleanup {
  const cleanups: ResizeCleanup[] = [];

  for (const element of elements) {
    if (element !== null && element !== undefined) {
      cleanups.push(observeResize(element, callback, options));
    }
  }

  return () => {
    for (const cleanup of cleanups) {
      cleanup();
    }
  };
}

/**
 * @file scheduleFrame - requestAnimationFrame wrapper with cleanup
 * @module @dsai-io/react/utils/layout
 *
 * A wrapper around requestAnimationFrame that provides automatic cleanup,
 * SSR safety, and convenient scheduling patterns.
 *
 * Features:
 * - SSR-safe (uses setTimeout fallback when rAF unavailable)
 * - Automatic cleanup function returned
 * - Loop scheduling for continuous animations
 * - Delta time calculation
 * - TypeScript-friendly with strict types
 */

import { isBrowser } from '../browser/isBrowser';

/**
 * Frame callback with timing information
 */
export interface FrameInfo {
  /** Current timestamp (performance.now() or Date.now()) */
  readonly timestamp: number;
  /** Time since last frame in milliseconds */
  readonly deltaTime: number;
  /** Total elapsed time since start in milliseconds */
  readonly elapsedTime: number;
  /** Frame count since start */
  readonly frameCount: number;
}

/**
 * Frame callback function
 */
export type FrameCallback = (info: FrameInfo) => void;

/**
 * Loop callback function - return false to stop the loop
 */
export type LoopCallback = (info: FrameInfo) => boolean | undefined;

/**
 * Cleanup function to cancel scheduled frame
 */
export type FrameCleanup = () => void;

/**
 * Schedules a single frame callback.
 *
 * @param callback - Function to call on next animation frame
 * @returns Cleanup function to cancel the scheduled frame
 *
 * @example
 * ```tsx
 * // Schedule a single frame
 * const cancel = scheduleFrame((info) => {
 *   console.log(`Frame at ${info.timestamp}ms`);
 * });
 *
 * // Cancel if needed
 * cancel();
 *
 * // In React useEffect
 * useEffect(() => {
 *   const cancel = scheduleFrame(() => {
 *     element.style.transform = 'translateX(100px)';
 *   });
 *   return cancel;
 * }, []);
 * ```
 */
export function scheduleFrame(callback: FrameCallback): FrameCleanup {
  const startTime = getTimestamp();
  let cancelled = false;
  let frameId: number | ReturnType<typeof setTimeout> | null = null;

  const wrappedCallback = (timestamp: number): void => {
    if (cancelled) {
      return;
    }

    const info: FrameInfo = {
      timestamp,
      deltaTime: 0, // No previous frame for single schedule
      elapsedTime: timestamp - startTime,
      frameCount: 1,
    };

    callback(info);
  };

  // SSR safety check
  if (!isBrowser()) {
    return () => {
      cancelled = true;
    };
  }

  // Use rAF if available, otherwise setTimeout
  // Access through window to ensure testability with mocks
  const raf = typeof window !== 'undefined' ? window.requestAnimationFrame : undefined;
  if (typeof raf === 'function') {
    frameId = raf(wrappedCallback);
  } else if (typeof requestAnimationFrame === 'function') {
    frameId = requestAnimationFrame(wrappedCallback);
  } else {
    frameId = setTimeout(() => {
      wrappedCallback(getTimestamp());
    }, 16); // ~60fps fallback
  }

  return () => {
    cancelled = true;
    if (frameId !== null) {
      // Access through window to ensure testability with mocks
      const caf = typeof window !== 'undefined' ? window.cancelAnimationFrame : undefined;
      if (typeof caf === 'function' && typeof frameId === 'number') {
        caf(frameId);
      } else if (typeof cancelAnimationFrame === 'function' && typeof frameId === 'number') {
        cancelAnimationFrame(frameId);
      } else if (typeof frameId !== 'number') {
        clearTimeout(frameId);
      }
    }
  };
}

/**
 * Schedules multiple frames to run after a delay.
 *
 * @param callback - Function to call on each frame
 * @param delayFrames - Number of frames to wait before calling
 * @returns Cleanup function to cancel
 *
 * @example
 * ```tsx
 * // Wait 3 frames before running
 * const cancel = scheduleFrameAfter(() => {
 *   doSomething();
 * }, 3);
 * ```
 */
export function scheduleFrameAfter(callback: FrameCallback, delayFrames: number): FrameCleanup {
  if (delayFrames <= 0) {
    return scheduleFrame(callback);
  }

  let framesRemaining = delayFrames;
  let cancelled = false;
  let currentCancel: FrameCleanup | null = null;

  const tick = (): void => {
    if (cancelled) {
      return;
    }

    framesRemaining--;

    if (framesRemaining <= 0) {
      currentCancel = scheduleFrame(callback);
    } else {
      currentCancel = scheduleFrame(tick as unknown as FrameCallback);
    }
  };

  currentCancel = scheduleFrame(tick as unknown as FrameCallback);

  return () => {
    cancelled = true;
    if (currentCancel !== null) {
      currentCancel();
    }
  };
}

/**
 * Starts an animation loop that runs on each frame.
 *
 * @param callback - Function called on each frame. Return false to stop the loop.
 * @returns Cleanup function to stop the loop
 *
 * @example
 * ```tsx
 * // Continuous animation loop
 * const stop = startLoop((info) => {
 *   element.style.transform = `translateX(${Math.sin(info.elapsedTime / 1000) * 100}px)`;
 *
 *   // Stop after 5 seconds
 *   if (info.elapsedTime > 5000) {
 *     return false;
 *   }
 * });
 *
 * // Or stop manually
 * stop();
 * ```
 */
export function startLoop(callback: LoopCallback): FrameCleanup {
  const startTime = getTimestamp();
  let lastTime = startTime;
  let frameCount = 0;
  let cancelled = false;
  let frameId: number | ReturnType<typeof setTimeout> | null = null;

  const tick = (timestamp: number): void => {
    if (cancelled) {
      return;
    }

    frameCount++;
    const deltaTime = timestamp - lastTime;
    const elapsedTime = timestamp - startTime;
    lastTime = timestamp;

    const info: FrameInfo = {
      timestamp,
      deltaTime,
      elapsedTime,
      frameCount,
    };

    const shouldContinue = callback(info);

    // Continue loop unless explicitly stopped
    if (shouldContinue !== false && !cancelled) {
      scheduleNextFrame();
    }
  };

  const scheduleNextFrame = (): void => {
    if (!isBrowser()) {
      return;
    }

    // Access through window to ensure testability with mocks
    const raf = typeof window !== 'undefined' ? window.requestAnimationFrame : undefined;
    if (typeof raf === 'function') {
      frameId = raf(tick);
    } else if (typeof requestAnimationFrame === 'function') {
      frameId = requestAnimationFrame(tick);
    } else {
      frameId = setTimeout(() => {
        tick(getTimestamp());
      }, 16);
    }
  };

  // Start the loop
  scheduleNextFrame();

  return () => {
    cancelled = true;
    if (frameId !== null) {
      // Access through window to ensure testability with mocks
      const caf = typeof window !== 'undefined' ? window.cancelAnimationFrame : undefined;
      if (typeof caf === 'function' && typeof frameId === 'number') {
        caf(frameId);
      } else if (typeof cancelAnimationFrame === 'function' && typeof frameId === 'number') {
        cancelAnimationFrame(frameId);
      } else if (typeof frameId !== 'number') {
        clearTimeout(frameId);
      }
    }
  };
}

/**
 * Gets the current timestamp using performance.now() or Date.now() fallback.
 */
function getTimestamp(): number {
  if (isBrowser() && typeof performance !== 'undefined' && typeof performance.now === 'function') {
    return performance.now();
  }
  return Date.now();
}

/**
 * @file throttleFrame - Throttle function to animation frame
 * @module @dsai-io/react/utils/layout
 *
 * Throttles function execution to animation frames, ensuring smooth
 * animations and preventing excessive callback execution.
 *
 * Features:
 * - Limits execution to once per animation frame
 * - SSR-safe (uses setTimeout fallback)
 * - Preserves function signature
 * - Provides cancel and flush methods
 * - TypeScript-friendly with generic types
 */

import { isBrowser } from '../browser/isBrowser';

/**
 * Throttled function interface with control methods
 */
export interface ThrottledFrameFunction<T extends (...args: unknown[]) => unknown> {
  /** Call the throttled function */
  (...args: Parameters<T>): void;
  /** Cancel any pending frame */
  cancel(): void;
  /** Execute immediately if pending */
  flush(): void;
  /** Check if a call is pending */
  readonly pending: boolean;
}

/**
 * Options for throttleFrame
 */
export interface ThrottleFrameOptions {
  /**
   * Execute on leading edge (immediate first call).
   * @default true
   */
  leading?: boolean;

  /**
   * Execute on trailing edge (after last call).
   * @default true
   */
  trailing?: boolean;
}

/**
 * Throttles a function to execute at most once per animation frame.
 *
 * @param fn - Function to throttle
 * @param options - Optional configuration
 * @returns Throttled function with cancel/flush methods
 *
 * @example
 * ```tsx
 * // Throttle scroll handler
 * const handleScroll = throttleFrame((event: Event) => {
 *   updateScrollPosition();
 * });
 *
 * window.addEventListener('scroll', handleScroll);
 *
 * // Cleanup
 * window.removeEventListener('scroll', handleScroll);
 * handleScroll.cancel();
 *
 * // Check if pending
 * if (handleScroll.pending) {
 *   handleScroll.flush(); // Execute immediately
 * }
 *
 * // With options
 * const handleResize = throttleFrame(updateLayout, {
 *   leading: false,  // Don't execute on first call
 *   trailing: true,  // Execute after last call
 * });
 * ```
 */
export function throttleFrame<T extends (...args: unknown[]) => unknown>(
  fn: T,
  options: ThrottleFrameOptions = {}
): ThrottledFrameFunction<T> {
  const { leading = true, trailing = true } = options;

  let frameId: number | ReturnType<typeof setTimeout> | null = null;
  let lastArgs: Parameters<T> | null = null;
  let isPending = false;
  let hasLeadingCall = false;

  const cancelFrame = (): void => {
    if (frameId !== null) {
      // Access through window to ensure testability with mocks
      const caf = typeof window !== 'undefined' ? window.cancelAnimationFrame : undefined;
      if (isBrowser() && typeof caf === 'function' && typeof frameId === 'number') {
        caf(frameId);
      } else if (
        isBrowser() &&
        typeof cancelAnimationFrame === 'function' &&
        typeof frameId === 'number'
      ) {
        cancelAnimationFrame(frameId);
      } else if (typeof frameId !== 'number') {
        clearTimeout(frameId);
      }
      frameId = null;
    }
  };

  const scheduleFrame = (callback: () => void): void => {
    if (!isBrowser()) {
      // SSR - execute synchronously
      callback();
      return;
    }

    // Access through window to ensure testability with mocks
    const raf = typeof window !== 'undefined' ? window.requestAnimationFrame : undefined;
    if (typeof raf === 'function') {
      frameId = raf(callback);
    } else if (typeof requestAnimationFrame === 'function') {
      frameId = requestAnimationFrame(callback);
    } else {
      frameId = setTimeout(callback, 16);
    }
  };

  const execute = (): void => {
    isPending = false;
    frameId = null;
    hasLeadingCall = false;

    if (lastArgs !== null) {
      const args = lastArgs;
      lastArgs = null;
      fn(...args);
    }
  };

  const throttled = ((...args: Parameters<T>): void => {
    lastArgs = args;

    // Leading edge execution
    if (leading && !hasLeadingCall && !isPending) {
      hasLeadingCall = true;
      fn(...args);
      // Clear lastArgs after leading call - we only want trailing if NEW calls come in
      lastArgs = null;

      // Schedule frame to reset leading flag
      if (trailing) {
        isPending = true;
        scheduleFrame(() => {
          isPending = false;
          hasLeadingCall = false;

          // Execute trailing if there were calls during the frame
          if (lastArgs !== null && trailing) {
            const trailingArgs = lastArgs;
            lastArgs = null;
            fn(...trailingArgs);
          }
        });
      } else {
        // Just reset after frame
        scheduleFrame(() => {
          hasLeadingCall = false;
        });
      }
      return;
    }

    // Already pending - just update args for trailing execution
    if (isPending) {
      return;
    }

    // Schedule trailing execution
    if (trailing) {
      isPending = true;
      scheduleFrame(execute);
    }
  }) as ThrottledFrameFunction<T>;

  throttled.cancel = (): void => {
    cancelFrame();
    lastArgs = null;
    isPending = false;
    hasLeadingCall = false;
  };

  throttled.flush = (): void => {
    if (isPending && lastArgs !== null) {
      cancelFrame();
      const args = lastArgs;
      lastArgs = null;
      isPending = false;
      hasLeadingCall = false;
      fn(...args);
    }
  };

  Object.defineProperty(throttled, 'pending', {
    get: () => isPending,
    enumerable: true,
  });

  return throttled;
}

/**
 * Creates a throttled callback that only runs once per animation frame.
 * Simpler API than throttleFrame when you don't need options.
 *
 * @param fn - Function to throttle
 * @returns Throttled function
 *
 * @example
 * ```tsx
 * const updatePosition = rafThrottle((x: number, y: number) => {
 *   element.style.transform = `translate(${x}px, ${y}px)`;
 * });
 *
 * document.addEventListener('mousemove', (e) => {
 *   updatePosition(e.clientX, e.clientY);
 * });
 * ```
 */
export function rafThrottle<T extends (...args: unknown[]) => unknown>(
  fn: T
): (...args: Parameters<T>) => void {
  let frameId: number | null = null;
  let lastArgs: Parameters<T> | null = null;

  return (...args: Parameters<T>): void => {
    lastArgs = args;

    if (frameId !== null) {
      return;
    }

    // Access through window to ensure testability with mocks
    const raf = typeof window !== 'undefined' ? window.requestAnimationFrame : undefined;
    if (
      !isBrowser() ||
      (typeof raf !== 'function' && typeof requestAnimationFrame !== 'function')
    ) {
      fn(...args);
      return;
    }

    const rafFn = typeof raf === 'function' ? raf : requestAnimationFrame;
    frameId = rafFn(() => {
      frameId = null;
      if (lastArgs !== null) {
        fn(...lastArgs);
        lastArgs = null;
      }
    });
  };
}
